<?php require_once __DIR__.'/_layout.php'; admin_bat_buoc_dang_nhap(); $id=(int)($_GET['id']??0);$st=$ket_noi->prepare('SELECT * FROM sach WHERE id=:id');$st->execute(['id'=>$id]);$sach=$st->fetch();if(!$sach){header('Location: sach.php');exit;}$loi='';$st=$ket_noi->prepare('SELECT COUNT(*) FROM chi_tiet_don_hang WHERE sach_id=:id');$st->execute(['id'=>$id]);$co_don=(bool)$st->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){if(!admin_kiem_tra_csrf())$loi='Yêu cầu không hợp lệ.';elseif($co_don)$loi='Không thể xóa sách đã phát sinh trong đơn hàng.';else try{$ket_noi->beginTransaction();$ket_noi->prepare('DELETE FROM danh_gia WHERE sach_id=:id')->execute(['id'=>$id]);$ket_noi->prepare('DELETE FROM sach WHERE id=:id')->execute(['id'=>$id]);$ket_noi->commit(); if(!empty($sach['file_anh_bia'])){@unlink(DUONG_DAN_GOC.'/uploads/'.$sach['file_anh_bia']);}header('Location: sach.php?deleted=1');exit;}catch(Throwable $e){if($ket_noi->inTransaction())$ket_noi->rollBack();$loi='Không thể xóa sách.';}}admin_header('Xóa sách');?><h1>Xóa sách</h1><?php if($loi):?><p class="notice error"><?=htmlspecialchars($loi)?></p><?php endif;?><form class="card" method="post"><input type="hidden" name="csrf" value="<?=admin_csrf()?>"><p>Bạn có chắc muốn xóa <b><?=htmlspecialchars($sach['tieu_de'])?></b>?</p><p class="muted"><?= $co_don ? 'Sách này đã xuất hiện trong đơn hàng nên chỉ có thể giữ lại để bảo toàn lịch sử.' : 'Thao tác sẽ xóa cả các đánh giá của sách và không thể hoàn tác.' ?></p><p class="actions"><?php if(!$co_don):?><button>Xóa vĩnh viễn</button><?php endif;?><a class="btn alt" href="sach.php">Quay lại</a></p></form><?php admin_footer();
